-- Phase 4: Service intervals and due engine. Additive PostgreSQL tenant upgrade only.

CREATE TABLE IF NOT EXISTS "ServiceItems" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Code" varchar(64) NOT NULL,
    "NameAr" varchar(128) NOT NULL,
    "NameEn" varchar(128) NOT NULL,
    "SortOrder" integer NOT NULL DEFAULT 0,
    "SuggestedIntervalHours" numeric(18,4),
    "IsActive" boolean NOT NULL DEFAULT true,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer NOT NULL DEFAULT 0,
    "UpdatedAt" timestamp with time zone NOT NULL,
    "UpdatedBy" integer NOT NULL DEFAULT 0,
    "DeletedAt" timestamp with time zone
);

CREATE UNIQUE INDEX IF NOT EXISTS "UX_ServiceItems_Code"
    ON "ServiceItems" ("Code") WHERE "DeletedAt" IS NULL;

