CREATE TABLE IF NOT EXISTS "ServiceIntervalDefinitions" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "GeneratorModelKey" varchar(128) NOT NULL,
    "ServiceItemId" integer NOT NULL REFERENCES "ServiceItems" ("Id") ON DELETE RESTRICT,
    "IntervalHours" numeric(18,4) NOT NULL,
    "Importance" integer NOT NULL DEFAULT 1,
    "WarningLeadHours" numeric(18,4),
    "Notes" varchar(1000),
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer NOT NULL DEFAULT 0,
    "UpdatedAt" timestamp with time zone NOT NULL,
    "UpdatedBy" integer NOT NULL DEFAULT 0,
    "DeletedAt" timestamp with time zone
);

CREATE UNIQUE INDEX IF NOT EXISTS "UX_ServiceIntervalDefinitions_Model_Item"
    ON "ServiceIntervalDefinitions" ("GeneratorModelKey", "ServiceItemId") WHERE "DeletedAt" IS NULL;

CREATE TABLE IF NOT EXISTS "ServiceReplacementRecords" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "GeneratorId" integer NOT NULL REFERENCES "Generators" ("Id") ON DELETE RESTRICT,
    "ServiceItemId" integer NOT NULL REFERENCES "ServiceItems" ("Id") ON DELETE RESTRICT,
    "Kind" integer NOT NULL DEFAULT 1,
    "HoursAtService" numeric(18,4) NOT NULL,
    "OccurredAtUtc" timestamp with time zone NOT NULL,
    "WorkPermitId" integer REFERENCES "WorkPermits" ("Id") ON DELETE RESTRICT,
    "IsEarly" boolean NOT NULL DEFAULT false,
    "EarlyReplacementReason" varchar(500),
    "IntervalHoursSnapshot" numeric(18,4),
    "Notes" varchar(1000),
    "VoidedAtUtc" timestamp with time zone,
    "VoidedByUserId" integer,
    "VoidReason" varchar(500),
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer NOT NULL DEFAULT 0,
    "UpdatedAt" timestamp with time zone NOT NULL,
    "UpdatedBy" integer NOT NULL DEFAULT 0,
    "DeletedAt" timestamp with time zone
);

CREATE INDEX IF NOT EXISTS "IX_ServiceReplacementRecords_Gen_Item_Hours"
    ON "ServiceReplacementRecords" ("GeneratorId", "ServiceItemId", "HoursAtService");

CREATE INDEX IF NOT EXISTS "IX_ServiceReplacementRecords_Voided"
    ON "ServiceReplacementRecords" ("GeneratorId", "ServiceItemId", "VoidedAtUtc");

CREATE TABLE IF NOT EXISTS "ServiceDueStates" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "GeneratorId" integer NOT NULL REFERENCES "Generators" ("Id") ON DELETE RESTRICT,
    "ServiceItemId" integer NOT NULL REFERENCES "ServiceItems" ("Id") ON DELETE RESTRICT,
    "CycleRecordId" integer REFERENCES "ServiceReplacementRecords" ("Id") ON DELETE SET NULL,
    "HighestNotifiedStatus" integer,
    "LastEvaluatedAtUtc" timestamp with time zone,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer NOT NULL DEFAULT 0,
    "UpdatedAt" timestamp with time zone NOT NULL,
    "UpdatedBy" integer NOT NULL DEFAULT 0,
    "DeletedAt" timestamp with time zone
);

CREATE UNIQUE INDEX IF NOT EXISTS "UX_ServiceDueStates_Generator_Item"
    ON "ServiceDueStates" ("GeneratorId", "ServiceItemId") WHERE "DeletedAt" IS NULL;
